Definition readsome_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (stateb ioc implb tgt tn ec lo : Z) (S : statev) (ds junk : list byte) (E : ecv) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (rs_take ds tn)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (stateb, stateb + SZ_SPCI_STATE); (ec, ec + 24); (tgt, tgt + tn)]%Z m m'
    /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ StateBlock LB m' stateb ioc implb (rs_state S ds tn) (skipn (Z.to_nat (rs_take ds tn)) ds)
    /\ rw_cells usegs m' tgt [CB (Z.to_nat (rs_take ds tn)) (firstn (Z.to_nat (rs_take ds tn)) ds);
                            CB (Z.to_nat (tn - rs_take ds tn)) (skipn (Z.to_nat (rs_take ds tn)) junk)]
    /\ rw_cells usegs m' ec (ErrCodeCells (if zlength ds =? 0 then EC_ts_eof else E))
    /\ XStatics m' /\ MiscVt48 m'.

Definition readsome_stmt : Prop :=
  forall (bs stateb ioc implb MB tgt tn ec lo : Z) (LB : list block) (S : statev) (ds junk : list byte) (E : ecv)
    ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  (* [comment removed for export] *)
  ro_cells usegs m bs [C8 (wz (stateb + O_SPC_STORAGE))] -> bs mod 8 = 0 ->
  (* [comment removed for export] *)
  StateBlock LB m stateb ioc implb S ds -> st_lk S = 0 -> (ds = [] -> st_code S = STREAM_EOF) ->
  st_nread S + 1 < 2^63 -> st_nread_bytes S + zlength ds < 2^63 ->
  (* [comment removed for export] *)
  ro_cells usegs m MB [C8 (wz tgt); C8 (wz tn)] -> MB mod 8 = 0 -> 1 <= tn < 2^63 ->
  rw_cells usegs m tgt [CB (Z.to_nat tn) junk] ->
  (* [comment removed for export] *)
  rw_cells usegs m ec (ErrCodeCells E) -> ec mod 8 = 0 ->
  (* [comment removed for export] *)
  XStatics m -> MiscVt48 m ->
  (* [comment removed for export] *)
  stk usegs m lo (bv_unsigned sp) -> lo + READSOME_STACK <= bv_unsigned sp -> hceil <= lo ->
  (* [comment removed for export] *)
  bv_unsigned sp <= bs -> bv_unsigned sp <= MB -> bv_unsigned sp <= ec ->
  tgt + tn <= hceil -> (tgt + tn <= stateb \/ stateb + SZ_SPCI_STATE <= tgt) ->
  (tgt + tn <= fb_begin (st_fb S) \/ fb_end (st_fb S) <= tgt) -> (tgt + tn <= 0x10000 \/ 0xb8000 <= tgt) ->
  (* [comment removed for export] *)
  (fb_end (st_fb S) <= stateb \/ stateb + SZ_SPCI_STATE <= fb_begin (st_fb S)) ->
  bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *)
  MB + 16 < 2^64 ->
  mem_inv usegs m ->
  evt usegs (readsome_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB stateb ioc implb tgt tn ec lo S ds junk E m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz bs) (wz MB) (wz ec) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_STREAM_READ_SOME) fc None m (seg_rom usegs)).

